        "Boşaltma sırasında sürekli gözetim yaparak erken uyarı işaretlerini takip etmek.",
        "Acil durumda ilk müdahale ekiplerini ve gerekiyorsa dış kurumları (itfaiye, çevre birimi) bilgilendirmek.",
