        "Tehlikeli Maddelerin Karayoluyla Taşınması Hakkında Yönetmelik (Ulaştırma ve Altyapı Bakanlığı) ve bu Yönetmeliğe dayanılarak yayımlanan tebliğ/genelgeler.",
